bounded_host_request.command:
set -eu
cid=gace-createvdobot-videobot-poll-1
test "$(docker inspect "$cid" --format '{{.State.Running}}')" = true
docker exec -i "$cid" node --input-type=module <<'NODE'
import pg from 'pg';
import {readFileSync} from 'node:fs';
import {createPostgresPostingReceiptStore} from '/opt/videobot/src/sales/pgPostingReceipts.mjs';
import {createPostgresListingStore} from '/opt/videobot/src/sales/pgListings.mjs';
const e=process.env;
const password=readFileSync(e.VIDEOBOT_DB_PASSWORD_FILE,'utf8').trim();
const url='postgresql://'+encodeURIComponent(e.VIDEOBOT_DB_USER)+':'+encodeURIComponent(password)+'@'+e.VIDEOBOT_DB_HOST+':5432/'+e.VIDEOBOT_DB_NAME;
const pool=new pg.Pool({connectionString:url,max:2,connectionTimeoutMillis:5000});
const id='389558ba-a38b-42a1-b92e-e98143df3e2d';
try{
 const q=await pool.query("SELECT seller_user_id,revision,status FROM videobot_listings WHERE listing_id=$1",[id]);
 if(q.rowCount!==1)throw Error('LISTING_NOT_UNIQUE');
 const owner=Number(q.rows[0].seller_user_id);
 const revision=Number(q.rows[0].revision);
 const status=q.rows[0].status;
 const receipts=createPostgresPostingReceiptStore(pool);
 const receipt=await receipts.read(id+':'+(status==='published'?revision-1:revision));
 if(!receipt||receipt.status!=='sent')throw Error('TELEGRAM_SEND_NOT_CONFIRMED');
 const free=(receipt.freeMessageIds??[]).map(Number);
 const paid=Number(receipt.paidMessageId);
 if(free.length!==2||free[0]===free[1]||
    free.some(x=>!Number.isSafeInteger(x)||x<1)||
    !Number.isSafeInteger(paid)||paid<1)throw Error('POST_MESSAGE_ID_READBACK_INVALID');
 if(status==='published'){console.log('VIDEO_ALREADY_PUBLISHED=PASS');}
 else {
  if(status!=='draft'&&status!=='ready')throw Error('LISTING_STATUS_REQUIRES_MANUAL_RECONCILE');
  const listings=createPostgresListingStore(pool);
  await listings.markPublished(owner,id,revision,{posted:true,freeMessageIds:free,paidMessageId:paid});
 }
 const latest=await pool.query("SELECT status,revision FROM videobot_listings WHERE listing_id=$1",[id]);
 if(latest.rows[0]?.status!=='published')throw Error('LISTING_PUBLISHED_READBACK_FAILED');
 console.log('VIDEO_PUBLICATION_DB=PASS');
 console.log('VIDEO_TOPIC_THREAD=1695');
 console.log('FREE_MESSAGE_IDS='+free.join(','));
 console.log('PAID_MESSAGE_ID='+paid);
 console.log('VIDEO_REVISION='+latest.rows[0].revision);
}finally{await pool.end()}
NODE
